export type BrandId = keyof typeof BRANDS | 'local' | 'custom';

export function BrandLogo({
  id,
  brand,
  size = 20,
  bare = false,
  label,
  className,
}: {
  id?: BrandId;
  brand?: BrandId;
  size?: number;
  bare?: boolean;
  label?: string;
  className?: string;
}) {
  const resolved: BrandId = id ?? brand ?? 'local';
  if (resolved === 'local' || resolved === 'custom') {
    const iconName = resolved === 'local' ? 'memory' : 'hub';
    if (bare) {
      return (
        <span
          role={label ? 'img' : undefined}
          aria-label={label}
          className={clsx('inline-flex shrink-0 items-center justify-center text-brand', className)}
          style={{ width: size, height: size }}
        >
          <GIcon name={iconName} size={Math.round(size * 0.88)} />
        </span>
      );
    }
    return (
      <span
        role={label ? 'img' : undefined}
        aria-label={label}
        className={clsx(
          'inline-flex shrink-0 items-center justify-center r-chip border border-line bg-surface-2 text-brand',
          className,
        )}
        style={{ width: size, height: size }}
      >
        <GIcon name={iconName} size={Math.round(size * 0.68)} />
      </span>
    );
  }

  const entry = BRANDS[resolved];
  const color = 'color' in entry ? entry.color : undefined;
  const glyphSize = bare ? size : Math.round(size * (resolved === 'telegram' ? 0.82 : 0.72));

  const svg = (
    <svg
      viewBox={entry.viewBox}
      width={glyphSize}
      height={glyphSize}
      fill={entry.mono || color ? 'currentColor' : undefined}
      style={color ? { color } : undefined}
      className={clsx('shrink-0 select-none', entry.mono && 'text-fg')}
      aria-hidden="true"
      focusable="false"
      dangerouslySetInnerHTML={{ __html: entry.body }}
    />
  );

  if (bare) {
    return (
      <span
        role={label ? 'img' : undefined}
        aria-label={label}
        className={clsx('inline-flex shrink-0 items-center justify-center', className)}
        style={{ width: size, height: size }}
      >
        {svg}
      </span>
    );
  }

  return (
    <span
      role={label ? 'img' : undefined}
      aria-label={label}
      className={clsx(
        'inline-flex shrink-0 items-center justify-center overflow-hidden r-chip border border-line bg-surface',
        className,
      )}
      style={{ width: size, height: size }}
    >
      {svg}
    </span>
  );
}
